# For each change, find nearest non-bg neighbor in ALL directions
def find_nearest_neighbors(grid, bg, pos, max_dist=3):
    sr, sc = pos
    neighbors = defaultdict(list)
    for dr in range(-max_dist, max_dist+1):
        for dc in range(-max_dist, max_dist+1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = sr + dr, sc + dc
            d = abs(dr) + abs(dc)
            while d <= max_dist:
                cr, cc = nr + dr*(d//abs(dr)) if dr!=0 else nc + dc*d, ...
